Function Suydien_Lietke(KB, q) return true or false
symbols=get_list_of_symbols(KB,q);
n= symbols.size();
int bộ_giá_tri[n]; //dùng để lưu bộ các giá trị logic (true:1, false:0)
for (i=1; i≤2^n; i++) {
    bộ_giá_tri [1,...,n]=generate(i); // sinh ra bộ thứ i
    if (evaluate(KB, bộ_giá_tri)==true && evaluate(q, bộ_giá_tri)=false)
        return false
return true;
